# 🟡 中风险：Atlas Schema 声明文件（atlas.hcl）
apiVersion: v1
kind: ConfigMap
metadata:
  name: atlas-schema
  namespace: database
data:
  schema.hcl: |
    schema "myapp" {}

    table "users" {
      schema = schema.myapp
      column "id" {
        type = bigint
        auto_increment = true
      }
      column "email" {
        type = varchar(255)
      }
      column "phone" {
        type = varchar(20)
        null = true
      }
      column "phone_verified" {
        type = boolean
        default = false
      }
      column "created_at" {
        type = timestamp
        default = sql("CURRENT_TIMESTAMP")
      }
      primary_key {
        columns = [column.id]
      }
      index "idx_email" {
        unique = true
        columns = [column.email]
      }
      index "idx_phone" {
        columns = [column.phone]
      }
    }
  atlas.hcl: |
    env "production" {
      src = "file://schema.hcl"
      dev = "docker://mysql/8/dev"
      url = "mysql://${DB_USER}:${DB_PASSWORD}@mysql-primary.database.svc:3306/myapp"
      migration {
        dir = "file://migrations"
        format = atlas
      }
      diff {
        skip {
          drop_schema = true
          drop_table = true
        }
      }
    }

-- 🟢 低风险：MySQL 查看锁等待（gh-ost 相关）
SELECT * FROM information_schema.INNODB_LOCK_WAITS;
SELECT * FROM information_schema.PROCESSLIST WHERE Command != 'Sleep' AND Time > 30;
